(()=>{const r=pokewatch.renderer,c=pokewatch.ctx,P=c.player;const W=r.width,H=r.height;const top=96,bot=76;
const ins=(x,z,eff)=>{const p=r.project(x,c.world.height(x,z),z);return p&&p[0]>=0&&p[0]<=W&&p[1]>=(eff?top:0)&&p[1]<=H-(eff?bot:0);};
const d=(dx,dz,eff)=>{let k=0;while(k<90&&ins(P.x+dx*k,P.z+dz*k,eff))k+=0.25;return k;};
const a=r.project(P.x,P.y,P.z),b=r.project(P.x,P.y+1,P.z);const art=r.sheets.get(P.species.id).art;
return {preset:r.cam.id,N:d(0,-1),S:d(0,1),E:d(1,0),W:d(-1,0),Neff:d(0,-1,1),Seff:d(0,1,1),jump1m:Math.round(a[1]-b[1]),spritePx:art.heightPx*r.pixelScale,scale:r.pixelScale,lines:r.canvas.height,enemiesOnScreen:(()=>{let n=0;const E=c.enemies;for(let i=0;i<E.hi;i++){if(!E.alive[i])continue;const p=r.project(E.x[i],E.y[i],E.z[i]);if(p&&p[0]>=0&&p[0]<=W&&p[1]>=0&&p[1]<=H)n++;}return n;})()};})()

